		/** 
		 * Tests creating a new Dimension.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Dimension");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Dimension" );

			try {            
				Dimension entity = DimensionService.getDimensionInstance().createDimension( generateNewEntity() );
				thePrimaryKey = entity.getDimensionId();
				LOGGER.info( "-- Successfully created a Dimension with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Dimension. 
		 */
		public Dimension testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Dimension" );

			Dimension entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Dimension with primary key" );
			msg.append( thePrimaryKey );
			
			DimensionFetchOneSummary fetchOneSummary = new DimensionFetchOneSummary( thePrimaryKey );

			try {
				entity = DimensionService.getDimensionInstance().getDimension( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Dimension " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Dimension.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Dimension." );

			StringBuilder msg = new StringBuilder( "Failed to update a Dimension : " );        
			Dimension entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Dimension." );

				// for use later on...
				thePrimaryKey = entity.getDimensionId();

				DimensionService proxy = DimensionService.getDimensionInstance();            
				proxy.updateDimension( entity );   

				LOGGER.info( "-- Successfully saved Dimension - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Dimension.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Dimension." );

			try{
			    Dimension entity = testRead(); 
				DimensionService.getDimensionInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Dimension with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Dimension with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Dimensions.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Dimensions:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Dimension : " );        
			List<Dimension> collection  = null;

			try {
				// call the static get method on the DimensionService
				collection = DimensionService.getDimensionInstance().getAllDimension();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Dimension entity = null;            
					Iterator<Dimension> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getDimensionId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

